"""Gate-level Python reconstruction of the supplied e46d90c3 invsqrt circuit.

Derived from the submitted instruction graph, not recovered upstream arithmetic
source. See NOTICE.txt and reconstruction.json for attribution and limitations.
The precursor uses ordinary CircuitBuilder calls; PP-005 is loaded separately.
Consecutive X sweeps use loops;
The two coefficient lookups are synthesized from quadratic/affine Boolean
certificates. There is no KMB/KMX, source string, or runtime input artifact. Decimal angle literals are passed as exact strings to Kickmix.
Names below mark observed regions, not proven high-level arithmetic routines.
"""
from pathlib import Path
import importlib.util
import hashlib
import io
import json

from lookup_certificate import emit as _emit_lookup

import kickmix as km

q = km.q
b = km.b


def _lookup(cb, which, wire_ids, outcome_ids):
    """Load A13/Hlow4 from a six-input GF(2) plan, retaining HMR debts.

    IDs describe the existing owner allocation, not lookup truth values.
    The unchanged later cleanup still owns every supplied measurement bit.
    """
    path = Path(__file__).resolve().parent/'data/lookup64_certificates.json'
    certificate = json.loads(path.read_text(encoding='utf-8'))['loaders'][which]
    return _emit_lookup(cb, certificate, [q(i) for i in wire_ids], [b(i) for i in outcome_ids])


