def early_phase(cb):
    """Observed operation interval [208, 238); preserves measurement order."""
    cb.z_pow(q(35), '0.5')
    cb.z_pow(q(36), '1.5')
    cb.z_pow(q(21), '0.5')
    cb.ccx(q(36), q(1), q(21))
    cb.z_pow(q(21), '1.5')
    cb.x(q(0))
    cb.cx(q(21), q(0))
    cb.x(q(1))
    cb.cx(q(21), q(1))
    cb.cx(q(26), q(22))
