def dead_write_candidate(cb):
    """Unprocessed CCX; its HMR remains at the original later position."""
    cb.ccx(q(16), q(20), q(21))

def pre_phase(cb):
    """Observed operation interval [3294, 7681); preserves measurement order."""
    cb.cx(q(18), q(16))
    cb.cx(q(12), q(10))
    cb.cx(q(12), q(11))
    cb.cx(q(12), q(13))
    cb.ccx(q(10), q(11), q(13))
    cb.cx(q(11), q(10))
    for wire in (45, 42, 41, 10):
        cb.x(q(wire))
    cb.cx(q(10), q(45))
    cb.cx(q(10), q(42))
    cb.cx(q(10), q(41))
    cb.cx(q(27), q(37))
    cb.cx(q(27), q(45))
    cb.ccx(q(37), q(45), q(40))
    cb.cx(q(27), q(40))
    cb.cx(q(27), q(37))
    cb.cx(q(37), q(45))
    cb.cx(q(40), q(38))
